import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Docker 部署","description":"使用镜像 kirizuofficial/kirivers 运行 KiriVers，并连接外部 PostgreSQL。","frontmatter":{"title":"Docker 部署","description":"使用镜像 kirizuofficial/kirivers 运行 KiriVers，并连接外部 PostgreSQL。"},"headers":[],"relativePath":"guide/install/docker.md","filePath":"guide/install/docker.md","lastUpdated":1790057721000}`),a={name:`guide/install/docker.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to “Docker 部署”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">镜像名称</p><p>镜像名是 <strong><code>kirizuofficial/kirivers</code></strong>。拉取哪一个标签以当前 Docker Hub 与 GitHub Release 为准。官方镜像已内嵌管理台，不必挂载或拷贝 <code>frontend/dist</code>。</p></div><table tabindex="0"><thead><tr><th>标签</th><th>含义</th></tr></thead><tbody><tr><td><code>latest</code></td><td>指向最近一次发版</td></tr><tr><td><code>&lt;semver&gt;</code>（如 <code>0.3.0</code>，无 <code>v</code> 前缀）</td><td>该版本的多架构 manifest，<code>docker pull</code> 自动挑你所在架构</td></tr><tr><td><code>&lt;semver&gt;_amd64</code> / <code>&lt;semver&gt;_arm64</code></td><td>该版本的单架构镜像，只在明确指定架构时用</td></tr></tbody></table><p>镜像支持 <code>linux/amd64</code> 与 <code>linux/arm64</code>（Alpine 基底、musl 构建）。其他 Linux 架构没有官方镜像，请用 <a href="/guide/install/#releases-files">Releases 的 glibc 产物</a> 或自编译。</p><p>镜像是发布单位；容器是运行单位。</p><p>PostgreSQL 必须先存在（另一容器、托管库或宿主机）。本页的 <code>docker run</code> 不附带数据库。需要一键起库时用 <a href="/guide/install/compose">Compose</a>。</p><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to “运行”">​</a></h2><p>把宿主机配置目录挂到容器内（目录中需有 <code>config.yaml</code>、<code>admin.yaml</code>、<code>client.yaml</code>），并映射双平面端口：</p><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirivers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8081:8081</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/kirivers/config:/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KIRIVERS_CONFIG=/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KIRIVERS_POSTGRES_DSN=&#39;host=host.docker.internal user=kirivers password=CHANGE_ME dbname=kirivers port=5432 sslmode=disable&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  kirizuofficial/kirivers</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>预期：容器保持运行；<code>docker logs kirivers</code> 出现 <code>:8080</code> / <code>:8081</code> 监听。浏览器打开宿主机 <code>http://127.0.0.1:8081</code>。</p><p>官方镜像已含管理台。<code>admin.yaml</code> 的 <code>static_dir</code> 指向管理台静态文件；文档站 VitePress <code>dist</code> 不是管理台。<code>static_dir: &quot;&quot;</code> 会关闭 UI。</p><details class="details custom-block"><summary>容器起来了但浏览器没有登录页</summary><p>确认映射了 <code>8081</code>，且容器内 <code>admin.yaml</code> 的 <code>static_dir</code> 不是空字符串。官方镜像已嵌入 UI，不要再挂载一份自建的 <code>frontend/dist</code>。</p></details><h2 id="日志、升级、数据" tabindex="-1">日志、升级、数据 <a class="header-anchor" href="#日志、升级、数据" aria-label="Permalink to “日志、升级、数据”">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>做法</th></tr></thead><tbody><tr><td>日志</td><td><code>docker logs -f kirivers</code>；同时可把 YAML 里的 <code>log.file.dir</code> 挂到卷</td></tr><tr><td>升级镜像</td><td><code>docker pull kirizuofficial/kirivers</code> 后重建容器；先备份 PostgreSQL 与 <code>storage.local.root</code></td></tr><tr><td>数据</td><td>数据库在 PostgreSQL 卷；安装包在对象存储或本地 <code>storage.local.root</code> 卷</td></tr></tbody></table><p>下一步：<a href="/guide/install/compose">Compose</a> 或 <a href="/guide/config/bootstrap-admin">管理员初始化</a>。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};